    /**
     * The low-frequency non-separable transform matrices of 8x8 blocks ({@code lowFreqTransMatrix}), by set and index.
     */
    static final int[][][] LFNST8 = split(decode(LFNST8_HEX, 6144), 48 * 16);

    /**
     * The low-frequency non-separable transform matrices of 4x4 blocks, by set and index.
     */
    static final int[][][] LFNST4 = split(decode(LFNST4_HEX, 2048), 16 * 16);

    /**
     * Prevents instantiation.
     */
    private VvcTransformTables() {
    }

    /**
     * Decodes signed bytes written in hexadecimal.
     *
     * @param hex the hexadecimal digits, two per value
     * @param count the number of values
     * @return the values
     */
    private static int[] decode(String hex, int count) {
        var out = new int[count];
        for (var i = 0; i < count; i++) {
            out[i] = (byte) Integer.parseInt(hex, 2 * i, 2 * i + 2, 16);
        }
        return out;
    }

    /**
     * Splits concatenated matrices into their four sets of two.
     *
     * @param all the matrices, set by set and index by index
     * @param size the coefficients per matrix
     * @return the matrices by set and index
     */
    private static int[][][] split(int[] all, int size) {
        var out = new int[4][2][size];
        for (var s = 0; s < 4; s++) {
            for (var k = 0; k < 2; k++) {
                System.arraycopy(all, (s * 2 + k) * size, out[s][k], 0, size);
            }
        }
        return out;
    }
